{
  "name": "OWIS PS10 电机定位控制器",
  "name_en": "OWIS PS10 Motor Positioning Controller",
  "manufacturer": "OWIS",
  "description": "这是一种用于驱动电动位移机构或步进电机轴的运动控制器，可对电机进行激活、参数配置、按位置计数移动，并读取运动状态与当前位置。它常用于实验室中的精密位移调节，如光学元件、样品台或旋转/线性平台的自动定位。",
  "description_en": "This is a motion controller for driving motorized positioning devices or stepper-motor axes. It can activate motors, configure motion-related parameters, move to a target position in counts, and report motion status and current position. It is commonly used in laboratories for precise positioning of optical components, sample stages, and linear or rotary translation assemblies.",
  "tag_hints": [
    "motorized positioning",
    "stepper motor control",
    "motion controller",
    "translation stage",
    "precision alignment",
    "optomechanics"
  ],
  "actions": [
    {
      "action_name": "auto-activate",
      "description": "激活指定电机，并在需要时使其退出错误状态。",
      "description_en": "Activate the selected motor and recover it from an error state if needed."
    },
    {
      "action_name": "auto-configure",
      "description": "配置指定电机的运动或参考参数。",
      "description_en": "Configure motion or reference settings for the selected motor."
    },
    {
      "action_name": "auto-move",
      "description": "使指定电机按绝对或相对计数移动到目标位置。",
      "description_en": "Move the selected motor to a target position using absolute or relative counts."
    },
    {
      "action_name": "auto-isMoving",
      "description": "查询指定电机当前是否正在运动。",
      "description_en": "Query whether the selected motor is currently moving."
    },
    {
      "action_name": "auto-getPos",
      "description": "读取当前位置计数。",
      "description_en": "Read the current position in counts."
    },
    {
      "action_name": "auto-setCurrents",
      "description": "设置指定电机的驱动电流、保持电流和电流模式。",
      "description_en": "Set the drive current, hold current, and current mode for the selected motor."
    }
  ]
}

